#!/usr/bin/env python3
"""At most two fixed free-model calls through the private gateway; synthetic snapshots only."""
import argparse
import base64
import gzip
import hashlib
import json
from pathlib import Path
import secrets
import sys
import time
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from free_model_client import FreeGatewayClient
from free_model_gateway import GatewayError
from hosted_free_models import MODELS
from shared_client import SharedClient
from shared_server import read_private_json
FIXTURES_SHA='5572f962aded51c3c56bedfd7d20fa30da8f41406ee3228ba5095feecedad207'
FIXTURES_B64=''


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--shared-config',type=Path,default=Path('/etc/chefjeff/shared-client.json'))
    args=parser.parse_args()
    client=FreeGatewayClient(SharedClient(read_private_json(args.shared_config)))
    raw=gzip.decompress(base64.b64decode(FIXTURES_B64,validate=True))
    if hashlib.sha256(raw).hexdigest()!=FIXTURES_SHA:raise ValueError()
    fixtures=json.loads(raw)
    if fixtures.get('synthetic_only') is not True:raise ValueError()
    payload=fixtures['cases'][0]['payload']
    client.request('catalog',{})
    rows=[]
    print('私密协调服务合成快照检查：每个固定免费模型最多一次，合计最多两次；不连接线上厨房。',flush=True)
    for provider in ('zhipu','startlux'):
        lease=None
        row={'provider':provider,'model':MODELS[provider]['model'],'valid_action':False}
        try:
            lease=client.request('reserve',{'provider':provider,'owner':secrets.token_urlsafe(24),'round':secrets.token_urlsafe(24)})
            started=time.monotonic()
            result=client.request('decide',{'lease':lease['lease'],'id':secrets.token_urlsafe(24),'payload':payload})
            row['gateway_request_ms']=round((time.monotonic()-started)*1000)
            answer=result['answer']
            if (answer.get('choice') not in payload['questions']['next_action']['criteria']
                    or type(answer.get('sprint')) is not bool):raise ValueError()
            row['valid_action']=True;row['within_15_seconds']=row['gateway_request_ms']<=15000
        except GatewayError as error:
            row['error']=error.code;row['status']=error.status
        except Exception:
            row['error']='invalid_or_local_failure'
        finally:
            if lease:
                try:client.request('release',{'lease':lease['lease']})
                except GatewayError:pass
        rows.append(row)
        print(json.dumps(row,ensure_ascii=False),flush=True)
    print(json.dumps({'site':client.site,'results':rows,'synthetic_only':True,'maximum_upstream_calls':2,
        'real_model_full_round_tested':False,'live_kitchen_contacted':False,'round_started':False,
        'research_consent_sent':False,'model_api_keys_read':False,'private_site_config_used':True,
        'credentials_printed':False,'player_database_opened':False},ensure_ascii=False,indent=2))


if __name__=='__main__':
    try:main()
    except Exception:raise SystemExit('协调服务检查已停止；未输出凭据、原始回复或玩家记录。') from None
